// Starting Tuning values and Setpoint
PID_PBand:=REAL#10;
PID_ITime:=T#1S;
PID_DTime:=T#1S;
PID_SP:=REAL#55;
// Remove this section when this logic is running in a PLC. these should
//all be retained variables that will be overwritten when tuning is done

// Starting Operation Settings Parameters
PID_OprSetParams.Alpha:=REAL#0.65;  //Setpoint filter for cascading, not relevant
PID_OprSetParams.ATCalcGain:= REAL#5;//1 = FAST, 10 = SLOW(influisce i tempi di reazione autotunning)
PID_OprSetParams.ATHystrs:=REAL#1;
PID_OprSetParams.MVLowLmt:=REAL#0;
PID_OprSetParams.MVUpLmt:=REAL#50; // Limite di regolazione autotunning 50 sono gli hz da mettere nell inverter

// Starting Initial Settings Parameters
PID_InitSetParams.DirOpr:=FALSE; //False = Heating, TRUE = Cooling
PID_InitSetParams.RngLowLmt:=REAL#0;
PID_InitSetParams.RngUpLmt:=REAL#4200;//Indica i pascal di impostazione
PID_InitSetParams.SampTime:=T#100ms; // The time period for PID processing
